import 'dart:convert';
import 'dart:typed_data';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter_tts/flutter_tts.dart';

import '../../../core/offline/local_database.dart';
import '../../../core/services/api_client.dart';

/// Speaks Mohajon AI answers aloud.
///
/// Prefers a natural female Bangla voice generated by the server
/// (`/api/v1/assistant/tts`, backed by Microsoft Edge's neural female Bangla
/// voice with a Google Translate fallback) and played through [AudioPlayer]. If the network voice is unavailable it falls
/// back to the device's built-in TTS engine so the assistant still speaks.
class MohajonTts {
  MohajonTts(this._db);

  final LocalDatabase _db;
  final AudioPlayer _player = AudioPlayer();
  final FlutterTts _deviceTts = FlutterTts();
  bool _deviceReady = false;

  Future<void> init() async {
    try {
      final languages = await _deviceTts.getLanguages;
      final bangla =
          languages
              .where(
                (l) =>
                    l.toString().toLowerCase().contains('bn') ||
                    l.toString().toLowerCase().contains('ben'),
              )
              .toList();
      if (bangla.isNotEmpty) {
        await _deviceTts.setLanguage(bangla.first.toString());
        await _deviceTts.setPitch(1.05);
        await _deviceTts.setSpeechRate(0.48);
        await _deviceTts.setVolume(1.0);
        _deviceReady = true;
      }
    } catch (_) {
      _deviceReady = false;
    }
  }

  Future<void> speak(String text) async {
    if (text.isEmpty) return;
    stop();
    try {
      final response = await ApiClient(_db).post('/api/v1/assistant/tts', {
        'text': text,
      }, timeout: const Duration(seconds: 60));
      final segments = (response['segments'] as List? ?? const [])
          .cast<String>();
      final mp3 = Uint8List.fromList(
        segments
            .map((s) => base64Decode(s))
            .expand((b) => b)
            .toList(growable: false),
      );
      if (mp3.isNotEmpty) {
        await _player.stop();
        await _player.play(BytesSource(mp3));
        return;
      }
    } catch (_) {
      // Network TTS failed; fall back to the device engine below.
    }
    await _speakDevice(text);
  }

  Future<void> _speakDevice(String text) async {
    if (!_deviceReady) return;
    try {
      await _deviceTts.stop();
      await _deviceTts.speak(text);
    } catch (_) {}
  }

  Future<void> stop() async {
    try {
      await _player.stop();
    } catch (_) {}
    try {
      await _deviceTts.stop();
    } catch (_) {}
  }

  Future<void> dispose() async {
    await stop();
    try {
      await _player.dispose();
    } catch (_) {}
  }
}